pub fn spiral(allocator: mem.Allocator, size: u16) mem.Allocator.Error![][]u16 {
    const n = @intCast(usize, size);
    var matrix = try allocator.alloc([]u16, n);
    errdefer allocator.free(matrix);

    var i: usize = 0;
    errdefer {
        while (i > 0) {
            i -= 1;
            allocator.free(matrix[i]);
        }
    }
    for (matrix) |*row| {
        row.* = try allocator.alloc(u16, n);
        i += 1;
    }

    if (n == 0) return matrix;

    var top: usize = 0;
    var bottom: usize = n - 1;
    var left: usize = 0;
    var right: usize = n - 1;
    var num: u16 = 1;

    while (top <= bottom and left <= right) {
        var col = left;
        while (col <= right) : (col += 1) {
            matrix[top][col] = num;
            num += 1;
